import { WORKOUTS } from '../workouts';
import type { LibraryMeal, LibraryProgram, LibraryLevel } from '../../lib/library';
import sourcedPrograms from './sourced-programs.json';
import somaxPrograms from './somax-programs.json';
import sourcedMeals from './sourced-meals.json';
import somaxMeals from './somax-meals.json';

// Curated library content, bundled with the app (this module is only
// loaded the first time the Library opens - see loadLibrary()).
// The JSON files are generated by the research agents in
// scripts/program-library/ and copied here once reviewed.

const BUILTIN_META: Record<string, { level: LibraryLevel; sport: string; goals: string[]; tags: string[]; description: string; daysPerWeek?: number; whoItsFor?: string; lifestyle?: string[] }> = {
  push: { level: 'beginner', sport: 'strength-training', goals: ['muscle', 'strength'], tags: ['barbell', 'dumbbells', 'cables'], description: 'Chest, shoulders and triceps - the classic push half of a push/pull/legs split.', daysPerWeek: 2, whoItsFor: 'Newer lifters on a push/pull/legs split - run each day once or twice a week.', lifestyle: ['full-gym'] },
  pull: { level: 'beginner', sport: 'strength-training', goals: ['muscle', 'strength'], tags: ['barbell', 'machines'], description: 'Back and biceps, built around the deadlift.', daysPerWeek: 2, whoItsFor: 'Newer lifters on a push/pull/legs split - pairs with Push Day and Leg Day.', lifestyle: ['full-gym'] },
  legs: { level: 'beginner', sport: 'strength-training', goals: ['muscle', 'strength'], tags: ['barbell', 'machines'], description: 'Squats, hinges and lunges for a full lower-body session.', daysPerWeek: 2, whoItsFor: 'Newer lifters on a push/pull/legs split who want a dedicated lower-body day.', lifestyle: ['full-gym'] },
  cond: { level: 'beginner', sport: 'hiit', goals: ['fat-loss', 'endurance'], tags: ['rower', 'kettlebell'], description: 'Short, hard conditioning circuit - rower intervals, swings and ropes.', daysPerWeek: 2, whoItsFor: 'Anyone short on time who wants a hard 30-minute conditioning hit.', lifestyle: ['time-efficient', 'busy'] },
  run: { level: 'beginner', sport: 'running', goals: ['endurance', 'general-fitness'], tags: [], description: 'An easy 30-minute steady run with a warm-up and cool-down.', daysPerWeek: 3, whoItsFor: 'People who can already jog for 20 minutes and want a simple steady run.', lifestyle: ['outdoor', 'minimal-equipment'] },
  walk: { level: 'beginner', sport: 'general', goals: ['general-fitness', 'fat-loss'], tags: [], description: 'A brisk walk plus a short stretch - the easiest way to start.', daysPerWeek: 5, whoItsFor: 'Total beginners, recovery days, or anyone getting back into exercise.', lifestyle: ['outdoor', 'minimal-equipment', 'older-adults'] },
  swim: { level: 'beginner', sport: 'swimming', goals: ['endurance'], tags: ['pool'], description: 'Warm-up, 6 x 100m intervals and an easy cool-down.', daysPerWeek: 2, whoItsFor: 'Comfortable swimmers who can swim 100m continuously.', lifestyle: [] },
  ride: { level: 'beginner', sport: 'cycling', goals: ['endurance'], tags: ['bike'], description: 'A steady 45-minute ride with an easy spin either side.', daysPerWeek: 2, whoItsFor: 'Riders who want an easy aerobic session on the road or a turbo.', lifestyle: ['outdoor'] },
};

const CURATED_AT = '2026-11-12T00:00:00Z';

const builtins: LibraryProgram[] = Object.entries(WORKOUTS).map(([key, w]) => {
  const m = BUILTIN_META[key];
  return {
    id: `somax-builtin-${key}`,
    kind: 'program',
    name: w.name,
    level: m?.level ?? 'beginner',
    sport: m?.sport ?? 'general',
    goals: m?.goals ?? ['general-fitness'],
    tags: m?.tags ?? [],
    category: w.category,
    duration: w.duration,
    description: m?.description ?? null,
    content: { exercises: w.exercises, daysPerWeek: m?.daysPerWeek, whoItsFor: m?.whoItsFor, lifestyle: m?.lifestyle },
    source: 'somax',
    credit_name: null,
    source_url: null,
    created_at: CURATED_AT,
  };
});

// Shape the research agents write (see scripts/program-library/).
interface RawProgram {
  id: string;
  name: string;
  series?: string;
  day?: number;
  daysInSeries?: number;
  daysPerWeek?: number;
  category: string;
  level: LibraryLevel;
  sport: string;
  goals: string[];
  duration: string;
  equipment?: string[];
  description: string;
  exercises: LibraryProgram['content']['exercises'];
  credit: string;
  sourceUrl: string;
  whoItsFor?: string;
  howToRun?: string[];
  lifestyle?: string[];
  sessionMinutes?: number;
}

interface RawMeal {
  id: string;
  name: string;
  mealType: string;
  level: LibraryLevel;
  goals: string[];
  diet?: string[];
  prepMinutes?: number;
  servings: number;
  kcal: number;
  proteinG: number;
  carbsG: number;
  fatG: number;
  ingredients: { name: string; amount: string }[];
  steps: string[];
  description: string;
  credit: string;
  sourceUrl: string;
  whoItsFor?: string;
  tips?: string[];
}

function fromRawProgram(r: RawProgram, source: 'somax' | 'credited'): LibraryProgram {
  return {
    id: `${source}-${r.id}`,
    kind: 'program',
    name: r.name,
    level: r.level,
    sport: r.sport,
    goals: r.goals ?? [],
    tags: r.equipment ?? [],
    category: r.category,
    duration: r.duration,
    description: r.description,
    content: {
      exercises: r.exercises,
      series: r.series,
      day: r.day,
      daysInSeries: r.daysInSeries,
      daysPerWeek: r.daysPerWeek,
      whoItsFor: r.whoItsFor,
      howToRun: r.howToRun,
      lifestyle: r.lifestyle,
      sessionMinutes: r.sessionMinutes,
    },
    source,
    credit_name: source === 'somax' ? null : r.credit,
    source_url: r.sourceUrl || null,
    created_at: CURATED_AT,
  };
}

function fromRawMeal(r: RawMeal, source: 'somax' | 'credited'): LibraryMeal {
  return {
    id: `${source}-${r.id}`,
    kind: 'meal',
    name: r.name,
    level: r.level,
    sport: null,
    goals: r.goals ?? [],
    tags: r.diet ?? [],
    category: r.mealType,
    duration: r.prepMinutes ? `${r.prepMinutes} min` : null,
    description: r.description,
    content: {
      servings: r.servings,
      kcal: r.kcal,
      proteinG: r.proteinG,
      carbsG: r.carbsG,
      fatG: r.fatG,
      ingredients: r.ingredients,
      steps: r.steps,
      prepMinutes: r.prepMinutes,
      whoItsFor: r.whoItsFor,
      tips: r.tips,
    },
    source,
    credit_name: source === 'somax' ? null : r.credit,
    source_url: r.sourceUrl || null,
    created_at: CURATED_AT,
  };
}

export const CURATED_PROGRAMS: LibraryProgram[] = [
  ...builtins,
  ...(somaxPrograms as RawProgram[]).map((r) => fromRawProgram(r, 'somax')),
  ...(sourcedPrograms as RawProgram[]).map((r) => fromRawProgram(r, 'credited')),
];

export const CURATED_MEALS: LibraryMeal[] = [
  ...(somaxMeals as RawMeal[]).map((r) => fromRawMeal(r, 'somax')),
  ...(sourcedMeals as RawMeal[]).map((r) => fromRawMeal(r, 'credited')),
];
